CREATE OR REPLACE FUNCTION public.queue_abandoned_upload_objects(_cutoff timestamptz) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE queued integer; BEGIN INSERT INTO public.document_storage_purge_queue(bucket,path) SELECT o.bucket_id,o.name FROM storage.objects o WHERE o.bucket_id IN ('talent-private-documents','talent-documents','talent-invite-docs','agency-compliance-docs') AND o.created_at >= timestamptz '2026-10-25T09:09:33Z' AND o.created_at < LEAST(_cutoff,now()-interval '24 hours') AND NOT EXISTS(SELECT 1 FROM public.talent_private_documents d WHERE d.storage_path=o.name) AND NOT EXISTS(SELECT 1 FROM public.talent_shared_documents d WHERE d.storage_path=o.name) AND NOT EXISTS(SELECT 1 FROM public.talent_shared_document_versions d WHERE d.storage_path=o.name) AND NOT EXISTS(SELECT 1 FROM public.talent_invitation_documents d WHERE d.storage_path=o.name) AND NOT EXISTS(SELECT 1 FROM public.agency_compliance_documents d WHERE d.storage_path=o.name) AND NOT EXISTS(SELECT 1 FROM public.document_storage_purge_queue q WHERE q.bucket=o.bucket_id AND q.path=o.name) ORDER BY o.created_at LIMIT 500; GET DIAGNOSTICS queued=ROW_COUNT; RETURN queued; END $$;
REVOKE ALL ON FUNCTION public.queue_abandoned_upload_objects(timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.queue_abandoned_upload_objects(timestamptz) TO service_role;